body.script:
    const core = document.querySelector("#core");
    const wrap = document.querySelector("#coreWrap");
    const fill = document.querySelector("#fill");
    const hits = document.querySelector("#hits");
    const luckCount = document.querySelector("#luckCount");
    const warning = document.querySelector("#warning");
    const crash = document.querySelector("#crash");
    const game = document.querySelector("#game");
    const cracks = document.querySelectorAll(".crack");
    const startScreen = document.querySelector("#startScreen");
    const play = document.querySelector("#play");
    const howTo = document.querySelector("#howTo");
    const history = document.querySelector("#history");
    const howToPage = document.querySelector("#howToPage");
    const historyPage = document.querySelector("#historyPage");
    const cheatPage = document.querySelector("#cheatPage");
    const bugPage = document.querySelector("#bugPage");
    const shopPage = document.querySelector("#shopPage");
    const infoPages = document.querySelectorAll(".info-page");
    const difficulty = document.querySelector("#difficulty");
    const difficultyLabel = document.querySelector("#difficultyLabel");
    const difficultyHelp = document.querySelector("#difficultyHelp");
    const addIntegrity = document.querySelector("#addIntegrity");
    const fullRepair = document.querySelector("#fullRepair");
    const breakNow = document.querySelector("#breakNow");
    const surviveNext = document.querySelector("#surviveNext");
    const cheats = document.querySelector("#cheats");
    const cheatsInGame = document.querySelector("#cheatsInGame");
    const bugs = document.querySelector("#bugs");
    const bugsInGame = document.querySelector("#bugsInGame");
    const shop = document.querySelector("#shop");
    const shopInGame = document.querySelector("#shopInGame");
    const fullscreenStart = document.querySelector("#fullscreenStart");
    const fullscreenGame = document.querySelector("#fullscreenGame");
    const unlockCode = document.querySelector("#unlockCode");
    const unlock = document.querySelector("#unlock");
    const probabilityLab = document.querySelector("#probabilityLab");
    const repairChance = document.querySelector("#repairChance");
    const deathChance = document.querySelector("#deathChance");
    const repairValue = document.querySelector("#repairValue");
    const deathValue = document.querySelector("#deathValue");
    const cheatStatus = document.querySelector("#cheatStatus");
    const bugScan = document.querySelector("#bugScan");
    const bugScanStatus = document.querySelector("#bugScanStatus");
    const moneyDisplay = document.querySelector("#money");
    const shopReplacements = document.querySelector("#shopReplacements");
    const cashOut = document.querySelector("#cashOut");
    const gambleReplacements = document.querySelector("#gambleReplacements");
     const resetProgress = document.querySelector("#resetProgress");
    const shopStatus = document.querySelector("#shopStatus");
    const skinCards = document.querySelectorAll("[data-skin-card]");
    const skinButtons = document.querySelectorAll("[data-skin]");
    const giveCommand = document.querySelector("#giveCommand");
    const executeGive = document.querySelector("#executeGive");
    const giveStatus = document.querySelector("#giveStatus");
    const CHEAT_CODE = "CORE-CTRL";
     const VERSION = "6.0.1";
    const difficultySettings = {
      1: { label: "RELAXED", damage: 5, repair: .15, death: .35 },
      2: { label: "STEADY", damage: 8, repair: .12, death: .45 },
      3: { label: "NORMAL", damage: 10, repair: .10, death: .50 },
      4: { label: "RISKY", damage: 15, repair: .06, death: .60 },
      5: { label: "BRUTAL", damage: 20, repair: .02, death: .70 }
    };
    let currentDifficulty = difficultySettings[difficulty.value];
    let customRepair = null, customDeath = null, forceSurvive = false;
    const skinPrices = { standard: 0, ice: 15, violet: 25, gold: 40, void: 60 };
    const ownedSkins = new Set(["standard"]);
    let money = 0, selectedSkin = "standard";
    let luckStreak = 0;
    const MAX_GIVE = 9999;
     let integrity = 100, started = false, crashed = false, resolving = false, activePage = false, audio;
     let rushActive = false, firstPressMade = false, idleRushTimer = null, rushTimer = null, rushCountdown = null, rushEndsAt = 0;

    function beep(freq, duration, type = "square", volume = .025) {
      try {
        audio ||= new (window.AudioContext || window.webkitAudioContext)();
        const o = audio.createOscillator(), g = audio.createGain();
        o.type = type; o.frequency.value = freq; g.gain.value = volume;
        o.connect(g); g.connect(audio.destination); o.start();
        g.gain.exponentialRampToValueAtTime(.0001, audio.currentTime + duration);
        o.stop(audio.currentTime + duration);
      } catch {}
    }
    function updateDifficulty() {
      currentDifficulty = difficultySettings[difficulty.value];
      difficultyLabel.textContent = currentDifficulty.label;
      difficultyHelp.textContent = `${currentDifficulty.damage} DAMAGE / ${currentDifficulty.repair * 100}% REPAIR / ${currentDifficulty.death * 100}% DEATH`;
    }
    function activeRules() {
      return {
        damage: currentDifficulty.damage,
        repair: customRepair === null ? currentDifficulty.repair : customRepair,
        death: customDeath === null ? currentDifficulty.death : customDeath
      };
    }
    function applyCoreGlow() {
      const glow = integrity <= 20 ? "glow-red" : integrity <= 40 ? "glow-orange" : integrity <= 60 ? "glow-yellow" : "";
      core.classList.remove("overheated", "glow-yellow", "glow-orange", "glow-red");
      fill.classList.remove("hot", "yellow", "orange", "red");
      if (glow) {
        core.classList.add(glow);
        fill.classList.add(glow.replace("glow-", ""));
      }
    }
    function updateShopUI() {
      moneyDisplay.textContent = money;
      shopReplacements.textContent = `PENDING REPLACEMENTS: ${luckStreak} / CASH VALUE: ${luckStreak * 10} THING$`;
      luckCount.textContent = luckStreak;
      skinCards.forEach(card => {
        const skin = card.dataset.skinCard;
        const button = card.querySelector("button");
        card.classList.toggle("active", selectedSkin === skin);
        button.textContent = selectedSkin === skin ? "EQUIPPED" : ownedSkins.has(skin) ? "EQUIP" : `BUY / ${skinPrices[skin]}$`;
        button.disabled = selectedSkin === skin;
      });
    }
    function applySkin(skin) {
      core.classList.remove("skin-ice", "skin-violet", "skin-gold", "skin-void");
      if (skin !== "standard") core.classList.add(`skin-${skin}`);
      selectedSkin = skin;
      updateShopUI();
    }
    function syncCoreDisplay() {
      const stage = 100 - integrity;
      hits.textContent = integrity;
      fill.style.width = integrity + "%";
      cracks.forEach((crack, index) => crack.classList.toggle("show", stage >= (index + 1) * 30));
      applyCoreGlow();
      if (integrity <= 50) {
        warning.textContent = integrity <= 20 ? "CRITICAL" : "UNSTABLE";
        warning.style.color = "var(--hot)";
      } else {
        warning.textContent = "STABLE"; warning.style.color = "";
      }
    }
    function clearIdleRushTimer() {
      if (idleRushTimer) {
        clearTimeout(idleRushTimer);
        idleRushTimer = null;
      }
    }
    function updateRushCountdown() {
      const seconds = Math.max(0, Math.ceil((rushEndsAt - Date.now()) / 1000));
      warning.textContent = `REPLACEMENT RUSH // ${seconds}s`;
      warning.style.color = "#ffd45c";
    }
    function collectRushReplacement() {
      luckStreak = Math.min(MAX_GIVE, luckStreak + 1);
      updateShopUI();
      wrap.classList.remove("hit"); void wrap.offsetWidth; wrap.classList.add("hit");
      core.classList.remove("boost"); void core.offsetWidth; core.classList.add("boost");
      updateRushCountdown();
      beep(1040, .08, "triangle", .035);
    }
    function endReplacementRush() {
      clearTimeout(rushTimer);
      clearInterval(rushCountdown);
      rushTimer = null; rushCountdown = null; rushActive = false;
      core.classList.remove("rush");
      syncCoreDisplay();
    }
    function startReplacementRush(guaranteed = false) {
      if (!started || crashed || resolving || rushActive) return;
      clearIdleRushTimer();
      rushActive = true;
      rushEndsAt = Date.now() + 20000;
      core.classList.add("rush");
      warning.textContent = guaranteed ? "GUARANTEED RUSH // 20s" : "REPLACEMENT RUSH // 20s";
      warning.style.color = "#ffd45c";
      beep(1180, .22, "sine", .05);
      rushCountdown = setInterval(updateRushCountdown, 250);
      rushTimer = setTimeout(endReplacementRush, 20000);
    }
    function cheatReady() {
      if (!started) {
        cheatStatus.textContent = "START THE GAME BEFORE USING GAMEPLAY CHEATS.";
        return false;
      }
      if (crashed || resolving || rushActive) {
        cheatStatus.textContent = rushActive ? "THE GOLD RUSH CORE CANNOT BE OVERRIDDEN." : "REBOOT OR WAIT FOR THE CORE TO RETURN.";
        return false;
      }
      return true;
    }
    function hit() {
      if (!started || crashed || resolving) return;
      firstPressMade = true;
      clearIdleRushTimer();
      if (rushActive) {
        collectRushReplacement();
        return;
      }
      if (Math.random() < .001) {
        startReplacementRush();
        collectRushReplacement();
        return;
      }
      const rules = activeRules();
      const repaired = Math.random() < rules.repair;
      if (repaired) {
        integrity = Math.min(100, integrity + 10);
        core.classList.remove("boost"); void core.offsetWidth; core.classList.add("boost");
        warning.textContent = "LUCKY +10";
        warning.style.color = "var(--acid)";
        beep(880, .12, "triangle", .04);
        setTimeout(() => {
          if (!crashed && !resolving) {
            warning.textContent = integrity <= 50 ? "UNSTABLE" : "STABLE";
            warning.style.color = integrity <= 50 ? "var(--hot)" : "";
          }
        }, 500);
      } else {
        integrity = Math.max(0, integrity - rules.damage);
        beep(120 + integrity * 5, .07, integrity < 40 ? "sawtooth" : "square");
      }
      const stage = 100 - integrity;
      hits.textContent = integrity;
      fill.style.width = integrity + "%";
      wrap.classList.remove("hit"); void wrap.offsetWidth; wrap.classList.add("hit");
      cracks.forEach((crack, index) => crack.classList.toggle("show", stage >= (index + 1) * 30));
      applyCoreGlow();
      if (integrity <= 50) {
        if (!repaired) {
          warning.textContent = integrity <= 20 ? "CRITICAL" : "UNSTABLE";
          warning.style.color = "var(--hot)";
        }
      } else {
        if (!repaired) {
          warning.textContent = "STABLE";
          warning.style.color = "";
        }
      }
      if (integrity === 0) {
        resolving = true;
        setTimeout(resolveBreak, 380);
      }
    }
    function startGame() {
      if (started) return;
      started = true;
      activePage = false;
      startScreen.classList.add("hidden");
      beep(440, .1, "triangle", .025);
      clearIdleRushTimer();
      firstPressMade = false;
      idleRushTimer = setTimeout(() => {
        if (!firstPressMade && started && !crashed && !rushActive) startReplacementRush(true);
      }, 60000);
      requestGameFullscreen();
    }
    async function requestGameFullscreen() {
      if (!document.fullscreenElement && document.documentElement.requestFullscreen) {
        try { await document.documentElement.requestFullscreen(); } catch {}
      }
      updateFullscreenLabels();
    }
    async function toggleFullscreen() {
      if (document.fullscreenElement) {
        try { await document.exitFullscreen(); } catch {}
      } else {
        await requestGameFullscreen();
      }
      updateFullscreenLabels();
    }
    function updateFullscreenLabels() {
      const label = document.fullscreenElement ? "EXIT FULLSCREEN" : "FULLSCREEN";
      fullscreenStart.textContent = label;
      fullscreenGame.textContent = label;
    }
    function openPage(page) {
      activePage = true;
      page.classList.add("visible");
    }
    function closePages() {
      activePage = false;
      infoPages.forEach(page => page.classList.remove("visible"));
    }
    function resolveBreak() {
      // Exactly one fair roll happens after the core reaches zero.
      const deathRoll = forceSurvive ? false : Math.random() < activeRules().death;
      forceSurvive = false;
      if (deathRoll) crashGame();
      else surviveBreak();
    }
    function crashGame() {
      luckStreak = 0; luckCount.textContent = 0;
      updateShopUI();
      crashed = true; game.classList.add("flash"); beep(48, .45, "sawtooth", .06);
      document.querySelector("#crash h2").innerHTML = "THE THING
BROKE.
YOU DIED.";
      document.querySelector("#crashMessage").textContent = "You died because you did exactly what the game asked. Reboot the core to try again.";
      setTimeout(() => crash.classList.add("visible"), 160);
    }
    function surviveBreak() {
      luckStreak++;
      luckCount.textContent = luckStreak;
      updateShopUI();
      beep(660, .14, "triangle", .04);
      // The replacement is automatic: the player keeps playing without rebooting.
      core.classList.add("flash");
      warning.textContent = "CORE REPLACED";
      warning.style.color = "var(--acid)";
      setTimeout(() => {
        integrity = 100; hits.textContent = 100; fill.style.width = "100%";
        applyCoreGlow(); core.classList.remove("flash");
        cracks.forEach(c => c.classList.remove("show"));
        warning.textContent = "STABLE"; resolving = false;
      }, 700);
    }
    function reset() {
      clearIdleRushTimer();
      clearTimeout(rushTimer); clearInterval(rushCountdown);
      rushTimer = null; rushCountdown = null; rushActive = false; firstPressMade = true;
      integrity = 100; luckStreak = 0; crashed = false; resolving = false; hits.textContent = 100; luckCount.textContent = 0; fill.style.width = "100%";
      updateShopUI();
      applyCoreGlow(); core.classList.remove("flash", "rush"); warning.textContent = "STABLE";
      warning.style.color = ""; cracks.forEach(c => c.classList.remove("show")); crash.classList.remove("visible");
      document.querySelector("#crash .eyebrow").textContent = "FATAL EXCEPTION // 0x00000001";
      document.querySelector("#crash h2").innerHTML = "THE THING
IS BROKEN.";
      document.querySelector("#crashMessage").textContent = "You died because you did exactly what the game asked.";
      document.querySelector("#crash p:nth-of-type(3)").innerHTML = "core_integrity: 0%
remaining_things: 0
recommended_action: do not touch the thing again";
    }
    function unlockProbabilityLab() {
      if (unlockCode.value.trim().toUpperCase() === CHEAT_CODE) {
        probabilityLab.classList.add("visible");
        cheatStatus.textContent = "PROBABILITY LAB UNLOCKED.";
        unlockCode.value = "";
      } else {
        cheatStatus.textContent = "ACCESS DENIED. TRY THE CODE YOU WERE GIVEN.";
      }
    }
    function changeRepairChance() {
      customRepair = Number(repairChance.value) / 100;
      repairValue.textContent = repairChance.value + "%";
      cheatStatus.textContent = "REPAIR CHANCE OVERRIDE ACTIVE.";
    }
    function changeDeathChance() {
      customDeath = Number(deathChance.value) / 100;
      deathValue.textContent = deathChance.value + "%";
      cheatStatus.textContent = "DEATH CHANCE OVERRIDE ACTIVE.";
    }
    function runGiveCommand() {
      const raw = giveCommand.value.trim();
      const normalized = raw.replace(/^\/\s*give\b/i, "/give");
      let parts = normalized.split(/\s+/);
      if (!/\s/.test(normalized)) {
        const skinMatch = normalized.match(/^\/give(?:[-_]?skin)[-_]?([a-z]+)$/i);
        const numberMatch = normalized.match(/^\/give[-_]?([a-z$]+)[-_]?(\d+)$/i);
        if (skinMatch) parts = ["/give", "skin", skinMatch[1]];
        else if (numberMatch) parts = ["/give", numberMatch[1], numberMatch[2]];
      }
      if (parts.length < 3 || parts[0].toLowerCase() !== "/give") {
        giveStatus.textContent = "USE: /give money 100, /give replacements 5, OR /give skin ice.";
        return;
      }
      const target = parts[1].toLowerCase();
      if (target === "skin" || target === "skins") {
        const skin = parts[2].toLowerCase();
        if (!skinPrices.hasOwnProperty(skin)) {
          giveStatus.textContent = "UNKNOWN SKIN. USE: standard, ice, violet, gold, OR void.";
          return;
        }
        ownedSkins.add(skin);
        applySkin(skin);
        giveStatus.textContent = `${skin.toUpperCase()} SKIN GRANTED AND EQUIPPED.`;
        giveCommand.value = "";
        return;
      }
      const rawAmount = Number(parts[2]);
      if (!Number.isFinite(rawAmount) || rawAmount <= 0) {
        giveStatus.textContent = "THE AMOUNT MUST BE A POSITIVE NUMBER.";
        return;
      }
      const amount = Math.min(MAX_GIVE, Math.floor(rawAmount));
      if (target === "money" || target === "things" || target === "thing$" || target === "cash") {
        money = Math.min(MAX_GIVE, money + amount);
        giveStatus.textContent = `GAVE ${amount} THING$. MAX: ${MAX_GIVE}.`;
      } else if (target === "replacements" || target === "replacement" || target === "luck") {
        luckStreak = Math.min(MAX_GIVE, luckStreak + amount);
        giveStatus.textContent = `GAVE ${amount} REPLACEMENTS. MAX: ${MAX_GIVE}.`;
      } else if (target === "integrity" || target === "core") {
        integrity = Math.min(100, integrity + amount);
        syncCoreDisplay();
        giveStatus.textContent = `GAVE ${amount} INTEGRITY. MAX: 100.`;
      } else {
        giveStatus.textContent = "UNKNOWN THING. USE MONEY, REPLACEMENTS, INTEGRITY, OR SKIN.";
        return;
      }
      updateShopUI();
      giveCommand.value = "";
    }
    addIntegrity.addEventListener("click", () => {
      if (!cheatReady()) return;
      integrity = Math.min(100, integrity + 10);
      syncCoreDisplay(); warning.textContent = "CHEAT +10"; warning.style.color = "var(--acid)";
      beep(880, .12, "triangle", .04);
    });
    fullRepair.addEventListener("click", () => {
      if (!cheatReady()) return;
      integrity = 100; syncCoreDisplay(); warning.textContent = "FULL REPAIR"; warning.style.color = "var(--acid)";
      beep(660, .16, "triangle", .04);
    });
    breakNow.addEventListener("click", () => {
      if (!cheatReady()) return;
      integrity = 0; syncCoreDisplay(); resolving = true; closePages();
      setTimeout(resolveBreak, 380);
    });
    surviveNext.addEventListener("click", () => {
      if (!cheatReady()) return;
      forceSurvive = true; cheatStatus.textContent = "NEXT BREAK GUARANTEED TO SURVIVE.";
    });
    howTo.addEventListener("click", () => openPage(howToPage));
    history.addEventListener("click", () => openPage(historyPage));
    cheats.addEventListener("click", () => openPage(cheatPage));
    cheatsInGame.addEventListener("click", () => openPage(cheatPage));
    bugs.addEventListener("click", () => openPage(bugPage));
    bugsInGame.addEventListener("click", () => openPage(bugPage));
    shop.addEventListener("click", () => openPage(shopPage));
    shopInGame.addEventListener("click", () => openPage(shopPage));
    cashOut.addEventListener("click", () => {
      if (resolving || crashed) {
        shopStatus.textContent = "WAIT FOR THE CORE RESULT BEFORE USING THE SHOP.";
        return;
      }
      if (!luckStreak) {
        shopStatus.textContent = "NO REPLACEMENTS TO CASH OUT.";
        return;
      }
      const payout = luckStreak * 10;
      money += payout; luckStreak = 0;
      shopStatus.textContent = `CASHED OUT ${payout} THING$.`;
      updateShopUI();
    });
    gambleReplacements.addEventListener("click", () => {
      if (resolving || crashed) {
        shopStatus.textContent = "WAIT FOR THE CORE RESULT BEFORE GAMBLING.";
        return;
      }
      if (!luckStreak) {
        shopStatus.textContent = "YOU NEED AT LEAST 1 REPLACEMENT TO GAMBLE.";
        return;
      }
      const before = luckStreak;
      const won = Math.random() < .5;
      if (won) {
        luckStreak = Math.min(MAX_GIVE, before - 1 + 2);
        shopStatus.textContent = `GAMBLE WON // ${before} → ${luckStreak} REPLACEMENTS.`;
      } else {
        luckStreak = before - 1;
        shopStatus.textContent = `GAMBLE LOST // ${before} → ${luckStreak} REPLACEMENTS.`;
      }
      updateShopUI();
    });
     resetProgress.addEventListener("click", () => {
       const confirmed = window.confirm("RESET ALL PROGRESS? This erases THING$, replacements, and unlocked skins.");
       if (!confirmed) return;
       money = 0;
       luckStreak = 0;
       ownedSkins.clear();
       ownedSkins.add("standard");
       applySkin("standard");
       shopStatus.textContent = "PROGRESS RESET. STANDARD CORE RESTORED.";
       updateShopUI();
     });
    skinButtons.forEach(button => button.addEventListener("click", () => {
      const skin = button.dataset.skin;
      const price = skinPrices[skin];
      if (!ownedSkins.has(skin)) {
        if (money < price) {
          shopStatus.textContent = `NOT ENOUGH THING$. NEED ${price}.`;
          return;
        }
        money -= price; ownedSkins.add(skin);
        shopStatus.textContent = `${skin.toUpperCase()} SKIN PURCHASED.`;
      }
      applySkin(skin);
      if (skin === selectedSkin) shopStatus.textContent = `${skin.toUpperCase()} SKIN EQUIPPED.`;
    }));
    bugScan.addEventListener("click", () => {
      bugScanStatus.textContent = "PATCH CHECK COMPLETE // 0 UNPATCHED ENTRIES // 5 PATCHES LOADED.";
    });
    fullscreenStart.addEventListener("click", toggleFullscreen);
    fullscreenGame.addEventListener("click", toggleFullscreen);
    document.addEventListener("fullscreenchange", updateFullscreenLabels);
    document.querySelectorAll("[data-close-page]").forEach(button => button.addEventListener("click", closePages));
    difficulty.addEventListener("input", updateDifficulty);
    unlock.addEventListener("click", unlockProbabilityLab);
    unlockCode.addEventListener("keydown", e => { if (e.key === "Enter") unlockProbabilityLab(); });
    repairChance.addEventListener("input", changeRepairChance);
    deathChance.addEventListener("input", changeDeathChance);
    executeGive.addEventListener("click", runGiveCommand);
    giveCommand.addEventListener("keydown", e => { if (e.key === "Enter") runGiveCommand(); });
    play.addEventListener("click", startGame);
    core.addEventListener("click", hit);
    document.addEventListener("keydown", e => {
      if (e.target.matches("input, textarea")) return;
      if (e.code === "Escape" && activePage) {
        e.preventDefault();
        closePages();
      } else if (e.code === "Space" || e.code === "Enter") {
        e.preventDefault();
        if (activePage) return;
        else if (!started) startGame();
        else if (e.code === "Space") hit();
      }
    });
    document.querySelector("#restart").addEventListener("click", reset);
    updateShopUI();
